package com.company.erp.productivity;

import static com.company.erp.productivity.ProductivityModels.*;

import com.company.erp.audit.AuditService;
import com.company.erp.company.CompanyAccess;
import com.company.erp.crm.CrmAccess;
import com.company.erp.pm.PmAccess;
import com.company.erp.workplace.WorkplaceAccess;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.ObjectMapper;

@Service
public class ProductivityService {
    private final JdbcClient jdbc;private final NamedParameterJdbcTemplate named;private final CompanyAccess companyAccess;
    private final PmAccess pmAccess;private final CrmAccess crmAccess;private final WorkplaceAccess workplaceAccess;
    private final AuditService audit;private final ObjectMapper json;
    public ProductivityService(JdbcClient jdbc,NamedParameterJdbcTemplate named,CompanyAccess companyAccess,
            PmAccess pmAccess,CrmAccess crmAccess,WorkplaceAccess workplaceAccess,AuditService audit,ObjectMapper json){
        this.jdbc=jdbc;this.named=named;this.companyAccess=companyAccess;this.pmAccess=pmAccess;this.crmAccess=crmAccess;
        this.workplaceAccess=workplaceAccess;this.audit=audit;this.json=json;
    }

    public ProductivitySummary summary(UUID companyId,Authentication auth){String subject=auth.getName();long unread=count("platform_notifications","target_subject=:subject and read_at is null and archived_at is null",companyId,subject);List<Map<String,Object>> inbox=inbox(companyId,auth);return new ProductivitySummary(unread,inbox.stream().filter(r->"APPROVAL".equals(text(r.get("item_type")))).count(),inbox.stream().filter(r->"SIGNATURE".equals(text(r.get("item_type")))).count(),inbox.stream().filter(r->"TASK".equals(text(r.get("item_type")))).count(),inbox.stream().filter(r->"HELPDESK".equals(text(r.get("item_type")))).count(),count("platform_saved_views","owner_subject=:subject",companyId,subject));}

    public List<SearchResult> search(UUID companyId,String query,Integer requestedLimit,Authentication auth){String q=query==null?"":query.trim();if(q.length()<2)bad("Search query must contain at least 2 characters");int limit=Math.max(1,Math.min(requestedLimit==null?20:requestedLimit,50));String like="%"+q+"%";List<SearchResult> out=new ArrayList<>();
        if(companyAccess.canAccess(auth,companyId,"pm.task.read"))for(Map<String,Object>r:rows("select t.id,t.code,t.title,s.name status,p.name project_name from pm_tasks t join pm_workflow_statuses s on s.id=t.status_id left join pm_projects p on p.id=t.project_id where t.company_id=:companyId and (t.code ilike :q or t.title ilike :q or coalesce(t.description,'') ilike :q) order by t.updated_at desc limit 80",params(companyId,"q",like)))if(pmAccess.canAccessTask(auth,companyId,id(r.get("id")),"pm.task.read"))out.add(result("TASK",r,"title","code","/pm/tasks"));
        if(companyAccess.canAccess(auth,companyId,"crm.customer.read"))for(Map<String,Object>r:rows("select id,customer_code code,display_name title,status from customers where company_id=:companyId and (coalesce(customer_code,'') ilike :q or display_name ilike :q or coalesce(email,'') ilike :q) order by updated_at desc limit 80",params(companyId,"q",like)))if(crmAccess.canAccessCustomer(auth,companyId,id(r.get("id")),"crm.customer.read"))out.add(result("CUSTOMER",r,"title","code","/crm/customers"));
        if(companyAccess.canAccess(auth,companyId,"document.read"))for(Map<String,Object>r:rows("select id,title,category subtitle,status from workplace_documents where company_id=:companyId and status<>'ARCHIVED' and (title ilike :q or coalesce(description,'') ilike :q or coalesce(category,'') ilike :q) order by updated_at desc limit 80",params(companyId,"q",like)))if(workplaceAccess.canReadDocument(auth,companyId,id(r.get("id")),"document.read"))out.add(result("DOCUMENT",r,"title","subtitle","/workplace/documents"));
        if(companyAccess.canAccess(auth,companyId,"knowledge.read"))for(Map<String,Object>r:rows("select a.id,a.title,s.name subtitle,a.status,s.scope_type,s.scope_id,s.owner_subject,a.author_subject from workplace_kb_articles a join workplace_kb_spaces s on s.id=a.space_id where a.company_id=:companyId and (a.title ilike :q or coalesce(a.summary,'') ilike :q or a.content ilike :q) order by a.updated_at desc limit 80",params(companyId,"q",like)))if(workplaceAccess.canAccessScope(auth,companyId,text(r.get("scope_type")),id(r.get("scope_id")))&&("PUBLISHED".equals(text(r.get("status")))||auth.getName().equals(text(r.get("author_subject")))||workplaceAccess.hasGlobal(auth,companyId,"knowledge.write")))out.add(result("KNOWLEDGE",r,"title","subtitle","/workplace/knowledge"));
        if(companyAccess.canAccess(auth,companyId,"approval.read"))for(Map<String,Object>r:rows("select id,title,request_number subtitle,status from workplace_approval_requests where company_id=:companyId and (title ilike :q or request_number ilike :q or coalesce(description,'') ilike :q) order by created_at desc limit 80",params(companyId,"q",like)))if(workplaceAccess.canAccessApproval(auth,companyId,id(r.get("id")),"approval.read"))out.add(result("APPROVAL",r,"title","subtitle","/workplace/approvals"));
        return out.stream().limit(limit).toList();}

    public List<Map<String,Object>> inbox(UUID companyId,Authentication auth){String subject=auth.getName();List<Map<String,Object>> out=new ArrayList<>();if(companyAccess.canAccess(auth,companyId,"approval.read"))out.addAll(rows("select 'APPROVAL' item_type,r.id,r.title,r.request_number reference,r.status,r.submitted_at occurred_at,'/workplace/approvals' path from workplace_approval_steps s join workplace_approval_requests r on r.id=s.approval_request_id where s.company_id=:companyId and s.approver_subject=:subject and s.status='PENDING'",params(companyId,"subject",subject)));if(companyAccess.canAccess(auth,companyId,"signature.read"))out.addAll(rows("select 'SIGNATURE' item_type,r.id,r.title,r.request_number reference,r.status,r.created_at occurred_at,'/workplace/signatures' path from workplace_signature_recipients s join workplace_signature_requests r on r.id=s.signature_request_id where s.company_id=:companyId and s.signer_subject=:subject and s.status='PENDING'",params(companyId,"subject",subject)));if(companyAccess.canAccess(auth,companyId,"helpdesk.read"))out.addAll(rows("select 'HELPDESK' item_type,t.id,t.subject title,t.ticket_number reference,t.status,t.created_at occurred_at,'/workplace/helpdesk' path from workplace_helpdesk_tickets t where t.company_id=:companyId and (t.assigned_subject=:subject or t.requester_subject=:subject) and t.status not in ('RESOLVED','CLOSED','CANCELLED')",params(companyId,"subject",subject)));if(companyAccess.canAccess(auth,companyId,"pm.task.read"))out.addAll(rows("select 'TASK' item_type,t.id,t.title,t.code reference,s.code status,coalesce(t.due_date,t.updated_at::date) occurred_at,'/pm/tasks' path from pm_tasks t join pm_workflow_statuses s on s.id=t.status_id join employees e on e.id=t.assignee_employee_id where t.company_id=:companyId and e.keycloak_subject=:subject and s.is_done=false",params(companyId,"subject",subject)));out.sort((a,b)->text(b.get("occurred_at")).compareTo(text(a.get("occurred_at"))));return out;}

    public List<Map<String,Object>> notifications(UUID companyId,Authentication auth,boolean includeArchived){String extra=includeArchived?"":" and archived_at is null";return rows("select id,title,body,category,severity,action_path,source_type,source_id,read_at,archived_at,created_at from platform_notifications where company_id=:companyId and target_subject=:subject"+extra+" order by created_at desc limit 200",params(companyId,"subject",auth.getName()));}
    @Transactional public CreatedResource createNotification(UUID companyId,NotificationRequest request,Authentication auth){String target=blank(request.targetSubject())==null?auth.getName():request.targetSubject().trim();if(!target.equals(auth.getName())&&!companyAccess.canAccess(auth,companyId,"notification.manage"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Notification management permission is required");if(!activeMember(companyId,target))bad("Notification target is not an active company member");UUID id=UUID.randomUUID();jdbc.sql("insert into platform_notifications(id,company_id,target_subject,title,body,category,severity,action_path,source_type,source_id,dedupe_key,created_by_subject) values(:id,:companyId,:target,:title,:body,:category,:severity,:path,:sourceType,:sourceId,:dedupe,:actor) on conflict(company_id,target_subject,dedupe_key) do update set title=excluded.title,body=excluded.body,severity=excluded.severity,action_path=excluded.action_path,archived_at=null").param("id",id.toString()).param("companyId",companyId.toString()).param("target",target).param("title",request.title()).param("body",blank(request.body())).param("category",blank(request.category())==null?"GENERAL":request.category()).param("severity",blank(request.severity())==null?"INFO":request.severity()).param("path",blank(request.actionPath())).param("sourceType",blank(request.sourceType())).param("sourceId",blank(request.sourceId())).param("dedupe",blank(request.dedupeKey())).param("actor",auth.getName()).update();audit.write(companyId,auth.getName(),"NOTIFICATION_CREATED","NOTIFICATION",id.toString(),"{}");return new CreatedResource(id,"CREATED");}
    @Transactional public CreatedResource markNotification(UUID companyId,UUID notificationId,String action,Authentication auth){if(!List.of("READ","UNREAD","ARCHIVE").contains(action))bad("Unsupported notification action");int changed=jdbc.sql("update platform_notifications set read_at=case when :action='READ' then current_timestamp when :action='UNREAD' then null else read_at end,archived_at=case when :action='ARCHIVE' then current_timestamp else archived_at end where company_id=:companyId and id=:id and target_subject=:subject").param("action",action).param("companyId",companyId.toString()).param("id",notificationId.toString()).param("subject",auth.getName()).update();if(changed==0)notFound("Notification not found");return new CreatedResource(notificationId,action);}
    public List<Map<String,Object>> preferences(UUID companyId,Authentication auth){return rows("select id,category,in_app_enabled,email_enabled,quiet_start,quiet_end,updated_at from platform_notification_preferences where company_id=:companyId and subject=:subject order by category",params(companyId,"subject",auth.getName()));}
    @Transactional public CreatedResource savePreference(UUID companyId,NotificationPreferenceRequest request,Authentication auth){UUID id=UUID.randomUUID();jdbc.sql("insert into platform_notification_preferences(id,company_id,subject,category,in_app_enabled,email_enabled,quiet_start,quiet_end) values(:id,:companyId,:subject,:category,:inApp,:email,:quietStart,:quietEnd) on conflict(company_id,subject,category) do update set in_app_enabled=excluded.in_app_enabled,email_enabled=excluded.email_enabled,quiet_start=excluded.quiet_start,quiet_end=excluded.quiet_end,updated_at=current_timestamp").param("id",id.toString()).param("companyId",companyId.toString()).param("subject",auth.getName()).param("category",request.category()).param("inApp",request.inAppEnabled()).param("email",request.emailEnabled()).param("quietStart",request.quietStart()).param("quietEnd",request.quietEnd()).update();return new CreatedResource(id,"SAVED");}

    public List<Map<String,Object>> savedViews(UUID companyId,String moduleKey,Authentication auth){Map<String,Object>p=params(companyId,"subject",auth.getName());String filter=blank(moduleKey)==null?"":" and module_key=:module";if(blank(moduleKey)!=null)p.put("module",moduleKey.trim());return rows("select id,module_key,name,config_json::text config_json,shared,default_view,owner_subject,created_at,updated_at from platform_saved_views where company_id=:companyId and (owner_subject=:subject or shared=true)"+filter+" order by default_view desc,name",p);}
    @Transactional public CreatedResource createSavedView(UUID companyId,SavedViewRequest request,Authentication auth){parseJson(request.configJson());if(request.shared()&&!companyAccess.canAccess(auth,companyId,"saved-view.share"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Saved view sharing permission is required");if(request.defaultView())jdbc.sql("update platform_saved_views set default_view=false where company_id=:companyId and owner_subject=:subject and module_key=:module").param("companyId",companyId.toString()).param("subject",auth.getName()).param("module",request.moduleKey()).update();UUID id=UUID.randomUUID();jdbc.sql("insert into platform_saved_views(id,company_id,owner_subject,module_key,name,config_json,shared,default_view) values(:id,:companyId,:subject,:module,:name,cast(:config as jsonb),:shared,:defaultView) on conflict(company_id,owner_subject,module_key,name) do update set config_json=excluded.config_json,shared=excluded.shared,default_view=excluded.default_view,updated_at=current_timestamp").param("id",id.toString()).param("companyId",companyId.toString()).param("subject",auth.getName()).param("module",request.moduleKey()).param("name",request.name()).param("config",request.configJson()).param("shared",request.shared()).param("defaultView",request.defaultView()).update();audit.write(companyId,auth.getName(),"SAVED_VIEW_UPSERTED","SAVED_VIEW",id.toString(),"{}");return new CreatedResource(id,"SAVED");}
    @Transactional public void deleteSavedView(UUID companyId,UUID viewId,Authentication auth){int changed=jdbc.sql("delete from platform_saved_views where company_id=:companyId and id=:id and owner_subject=:subject").param("companyId",companyId.toString()).param("id",viewId.toString()).param("subject",auth.getName()).update();if(changed==0)notFound("Saved view not found");}
    public List<Map<String,Object>> auditLogs(UUID companyId,AuditQuery query){Map<String,Object>p=params(companyId);String filter="";if(blank(query.action())!=null){filter+=" and action=:action";p.put("action",query.action().trim());}if(blank(query.resourceType())!=null){filter+=" and resource_type=:type";p.put("type",query.resourceType().trim());}if(blank(query.actor())!=null){filter+=" and actor_subject=:actor";p.put("actor",query.actor().trim());}p.put("limit",Math.max(1,Math.min(query.limit()==null?100:query.limit(),200)));return rows("select id,actor_subject,action,resource_type,resource_id,metadata,created_at from audit_logs where company_id=:companyId"+filter+" order by created_at desc limit :limit",p);}

    private long count(String table,String condition,UUID companyId,String subject){return jdbc.sql("select count(*) from "+table+" where company_id=:companyId and "+condition).param("companyId",companyId.toString()).param("subject",subject).query(Long.class).single();}
    private boolean activeMember(UUID companyId,String subject){return jdbc.sql("select count(*) from company_memberships where company_id=:companyId and keycloak_subject=:subject and status='ACTIVE'").param("companyId",companyId.toString()).param("subject",subject).query(Integer.class).single()>0;}
    private SearchResult result(String type,Map<String,Object>r,String title,String subtitle,String path){return new SearchResult(type,text(r.get("id")),text(r.get(title)),text(r.get(subtitle)),path,text(r.get("status")));}
    private Map<String,Object>params(UUID companyId,Object...pairs){Map<String,Object>p=new LinkedHashMap<>();p.put("companyId",companyId.toString());for(int i=0;i<pairs.length;i+=2)p.put(String.valueOf(pairs[i]),pairs[i+1]);return p;}
    private List<Map<String,Object>>rows(String sql,Map<String,Object>p){return named.queryForList(sql,p);}
    private void parseJson(String value){try{if(!json.readTree(value).isObject())bad("Saved view configuration must be a JSON object");}catch(ResponseStatusException ex){throw ex;}catch(Exception ex){bad("Saved view configuration is invalid JSON");}}
    private static UUID id(Object value){if(value==null||value.toString().isBlank())return null;return UUID.fromString(value.toString().trim());}private static String text(Object value){return value==null?"":value.toString();}private static String blank(String value){return value==null||value.isBlank()?null:value.trim();}private static void bad(String message){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}private static void notFound(String message){throw new ResponseStatusException(HttpStatus.NOT_FOUND,message);}
}
